#!/usr/bin/env bash
# Installs Abundant Doctrine into your Claude Code config directory:
# ${CLAUDE_CONFIG_DIR:-$HOME/.claude}. Safe to run again; a second run
# changes nothing.
#
#   bash install.sh
#
# What it does:
#   1. Checks for claude, git, node, jq and a logged-in gh. Stops if any is
#      missing, with the brew line for each.
#   2. Backs up anything it is about to change to <config>/backup-<timestamp>/.
#   3. Links <config>/abundant-doctrine to this folder, links
#      <config>/commands/wrap.md through it, and writes <config>/CLAUDE.md as a
#      short generated file that imports the kit's CLAUDE.md and your own
#      <config>/personal.md. A CLAUDE.md you already had moves to personal.md.
#   4. Merges settings.fragment.json into <config>/settings.json, keeping
#      everything of yours.
#   5. Installs the superpowers, supabase and vercel plugins.
#   6. Runs the guardrail tests.
set -u

kit=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)
marker='<!-- abundant-doctrine: generated by install.sh -->'
plugins="superpowers supabase vercel"
marketplace="claude-plugins-official"

die() { echo "install: $*" >&2; exit 1; }

# put SRC DEST: copy SRC beside DEST, then rename over it, so DEST is never
# half-written and a link at DEST is replaced rather than written through.
# An existing DEST keeps its permissions (settings.json can hold tokens).
put() {
  if [ -e "$2" ]; then
    cp -p "$2" "$2.abundant-new" && cat "$1" > "$2.abundant-new"
  else
    cp "$1" "$2.abundant-new"
  fi || die "could not write $2"
  if ! mv -f "$2.abundant-new" "$2"; then
    die "could not write $2"
  fi
}

# ---- 1. prerequisites ------------------------------------------------------
missing=""
for tool in claude git node jq gh; do
  command -v "$tool" > /dev/null 2>&1 && continue
  case "$tool" in
    claude) hint="brew install --cask claude-code" ;;
    *) hint="brew install $tool" ;;
  esac
  missing="$missing
  $tool: $hint"
done
if [ -n "$missing" ]; then
  die "missing prerequisites. Install them, then run this again:$missing"
fi
if ! gh auth status > /dev/null 2>&1; then
  die "gh is installed but not logged in. Run: gh auth login"
fi

# ---- where things go -------------------------------------------------------
config=${CLAUDE_CONFIG_DIR:-$HOME/.claude}
case "$config" in /*) ;; *) config="$PWD/$config" ;; esac
while [ "${#config}" -gt 1 ] && [ "${config%/}" != "$config" ]; do config=${config%/}; done
case "$config" in
  *" "* | *'"'* | *'$'* | *'`'*)
    die "your config directory's path ($config) contains a space, a double quote, a dollar sign or a backtick. The hook command runs through a shell and imports cannot point at it reliably; use a plain path." ;;
esac
if [ "$config" = "$HOME/.claude" ]; then
  # The import line is written for Claude Code to expand, not the shell.
  # shellcheck disable=SC2088
  shown="~/.claude"
else
  shown=$config
fi

link="$config/abundant-doctrine"
stub="$config/CLAUDE.md"
personal="$config/personal.md"
settings="$config/settings.json"
wrap="$config/commands/wrap.md"
wrap_target="$link/commands/wrap.md"
hook_cmd="node \"$link/hooks/careful.js\""

# ---- checks that must pass before anything is written ----------------------
[ -f "$kit/settings.fragment.json" ] || die "settings.fragment.json is missing from $kit"
[ -f "$kit/CLAUDE.md" ] || die "CLAUDE.md is missing from $kit"
[ -f "$kit/commands/wrap.md" ] || die "commands/wrap.md is missing from $kit"
if [ -e "$link" ] && [ ! -L "$link" ]; then
  die "$link exists and is not a link. Move it aside, then run this again."
fi
if [ -e "$settings" ] || [ -L "$settings" ]; then
  if ! jq -e 'type == "object"
      and ((.hooks // {}) | type == "object")
      and ((.hooks.PreToolUse // []) | type == "array")
      and ((.enabledPlugins // {}) | type == "object")' "$settings" > /dev/null 2>&1; then
    die "$settings is not valid settings JSON (an object, with hooks.PreToolUse a list). Nothing was changed. Fix or move it, then run this again."
  fi
fi

# The merged settings, computed now so a failure stops before any write.
work=$(mktemp -d) || die "could not make a temp directory"
trap 'rm -f "$work"/*; rmdir "$work" 2>/dev/null' EXIT
if [ -e "$settings" ]; then cp "$settings" "$work/current.json"; else echo '{}' > "$work/current.json"; fi
if ! jq --arg kit "$link" --arg cmd "$hook_cmd" --slurpfile frag "$kit/settings.fragment.json" '
    ($frag[0] | .hooks.PreToolUse |= map(.hooks |= map(.command |= sub("__KIT__"; $kit)))) as $f
    | def strip:
        if type == "object" and (.hooks | type) == "array"
           and any(.hooks[]; type == "object" and .command == $cmd)
        then (.hooks |= map(select((type == "object" and .command == $cmd) | not)))
             | if (.hooks | length) == 0 then empty else . end
        else . end;
    .enabledPlugins = ((.enabledPlugins // {}) + $f.enabledPlugins)
    | .hooks = (.hooks // {})
    | .hooks.PreToolUse = (((.hooks.PreToolUse // []) | map(strip)) + $f.hooks.PreToolUse)
  ' "$work/current.json" > "$work/settings.json"; then
  die "could not merge settings.fragment.json into $settings. Nothing was changed."
fi

printf '%s\n@%s/abundant-doctrine/CLAUDE.md\n@%s/personal.md\n' "$marker" "$shown" "$shown" > "$work/stub.md"

# ---- 2. backups, made only for what is about to change ---------------------
backup_dir=""
backup() { # backup PATH NAME-INSIDE-BACKUP
  if [ -z "$backup_dir" ]; then
    local base i=1
    base="$config/backup-$(date +%Y%m%d-%H%M%S)"
    backup_dir=$base
    while [ -e "$backup_dir" ]; do i=$((i + 1)); backup_dir="$base-$i"; done
    mkdir -p "$backup_dir" || die "could not create $backup_dir"
  fi
  mkdir -p "$(dirname "$backup_dir/$2")"
  cp -Pp "$1" "$backup_dir/$2" || die "could not back up $1"
}

mkdir -p "$config" || die "could not create $config"

stub_is_ours=no
if [ -f "$stub" ] && [ ! -L "$stub" ] && [ "$(sed -n 1p "$stub")" = "$marker" ]; then
  stub_is_ours=yes
fi
if [ -e "$stub" ] || [ -L "$stub" ]; then
  if ! { [ "$stub_is_ours" = yes ] && cmp -s "$stub" "$work/stub.md"; }; then
    backup "$stub" CLAUDE.md
  fi
fi
if [ "$stub_is_ours" = no ] && [ -e "$stub" ] && [ -s "$stub" ] && [ -e "$personal" ]; then
  backup "$personal" personal.md
fi
if [ -e "$wrap" ] || [ -L "$wrap" ]; then
  if ! { [ -L "$wrap" ] && [ "$(readlink "$wrap")" = "$wrap_target" ]; }; then
    backup "$wrap" commands/wrap.md
  fi
fi
if [ -e "$settings" ] && ! cmp -s "$settings" "$work/settings.json"; then
  backup "$settings" settings.json
fi

# ---- 3. links, personal file, generated CLAUDE.md --------------------------
if [ ! -L "$link" ] || [ "$(readlink "$link")" != "$kit" ]; then
  ln -sfn "$kit" "$link" || die "could not link $link"
fi

mkdir -p "$config/commands" || die "could not create $config/commands"
if [ ! -L "$wrap" ] || [ "$(readlink "$wrap")" != "$wrap_target" ]; then
  rm -f "$wrap"
  ln -s "$wrap_target" "$wrap" || die "could not link $wrap"
fi

# A CLAUDE.md of yours moves into personal.md, so nothing you relied on stops
# loading. personal.md is never overwritten, only appended to.
if [ ! -e "$personal" ]; then
  echo "<!-- Your own rules. The kit never changes this file. -->" > "$personal" || die "could not write $personal"
fi
if [ "$stub_is_ours" = no ] && [ -e "$stub" ] && grep -q '[^[:space:]]' "$stub"; then
  { echo; cat "$stub"; } >> "$personal" || die "could not move your CLAUDE.md into $personal"
  echo "Your CLAUDE.md moved into $personal (backup in $backup_dir)."
fi
if ! cmp -s "$stub" "$work/stub.md" 2> /dev/null || [ -L "$stub" ]; then
  put "$work/stub.md" "$stub"
fi

# ---- 4. settings -----------------------------------------------------------
if ! cmp -s "$settings" "$work/settings.json" 2> /dev/null; then
  put "$work/settings.json" "$settings"
fi

# ---- 5. plugins ------------------------------------------------------------
plugin_trouble=""
for p in $plugins; do
  if ! claude plugin install "$p@$marketplace"; then
    plugin_trouble="$plugin_trouble $p"
  fi
done

# ---- 6. guardrail tests ----------------------------------------------------
status=0
if node "$kit/hooks/careful.test.js" > /dev/null 2>&1; then
  echo "Guardrail tests: pass."
else
  echo "Guardrail tests FAILED. See why with: node \"$kit/hooks/careful.test.js\"" >&2
  status=1
fi

echo
echo "Abundant Doctrine is installed in $config."
[ -n "$backup_dir" ] && echo "Anything it replaced is in $backup_dir."
if [ -n "$plugin_trouble" ]; then
  echo "These plugins did not install:$plugin_trouble. In Claude Code, run /plugin and install them from $marketplace."
fi
echo "Your own rules go in $personal; the kit never changes that file."
echo "Next: read the README in $kit, then start claude in a project folder."
exit "$status"
